(function(){var reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;var video=document.querySelector('.l-fold-video');if(video){video.muted=true;video.defaultMuted=true;video.volume=0;var playing=video.play();if(playing&&playing.catch){playing.catch(function(){});}}
var reveals=document.querySelectorAll('[data-reveal]');if('IntersectionObserver'in window&&!reduced){var io=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-in');io.unobserve(entry.target);}});},{threshold:0.12,rootMargin:'0px 0px -8% 0px'});Array.prototype.forEach.call(reveals,function(el){io.observe(el);});}else{Array.prototype.forEach.call(reveals,function(el){el.classList.add('is-in');});}
document.addEventListener('click',function(e){var link=e.target.closest&&e.target.closest('a[href^="tel:"], a[href^="mailto:"]');if(!link||typeof window.gtag!=='function'){return;}
var href=link.getAttribute('href');window.gtag('event',href.indexOf('tel:')===0?'phone_click':'email_click',{link_url:href});});var card=document.querySelector('.l-survey');var grid=document.querySelector('.l-fold-grid');var wide=window.matchMedia('(min-width: 960px)');if(card&&grid&&'zoom'in card.style){var fitting=false;var fit=function(){if(fitting){return;}
fitting=true;card.style.zoom='';if(wide.matches){var cs=window.getComputedStyle(grid);var top=grid.getBoundingClientRect().top+window.scrollY;var room=window.innerHeight-top-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom);var need=card.offsetHeight;if(need>room){card.style.zoom=String(Math.max(0.8,room/need).toFixed(3));}}
fitting=false;};if('ResizeObserver'in window){var frameEl=card.querySelector('iframe');if(frameEl){new ResizeObserver(fit).observe(frameEl);}}
window.addEventListener('resize',fit,{passive:true});if(wide.addEventListener){wide.addEventListener('change',fit);}
fit();}
if(reduced){return;}
var closing=document.querySelector('.l-closing');var closingImg=document.querySelector('.l-closing-img');var queued=false;var frame=function(){queued=false;var vh=window.innerHeight;if(video){var y=Math.min(window.scrollY,vh);video.style.transform='translate3d(0, '+(y*0.16).toFixed(1)+'px, 0) scale('+(1+y/vh*0.04).toFixed(4)+')';}
if(closing&&closingImg){var r=closing.getBoundingClientRect();var t=Math.max(0,Math.min(1,(vh-r.top)/(vh+r.height)));closingImg.style.transform='translate3d(0, '+((t-0.5)*r.height*0.22).toFixed(1)+'px, 0)';}};var request=function(){if(!queued){queued=true;window.requestAnimationFrame(frame);}};window.addEventListener('scroll',request,{passive:true});window.addEventListener('resize',request,{passive:true});frame();})();